function makeImpulse(decay, len, seed){
  decay = decay != null ? decay : 3;
  len = len || 4000;
  var s = (seed>>>0) || 1;
  function rng(){ s = (s*1664525+1013904223)>>>0; return s/4294967296*2-1; }
  var ir = new Array(len);
  for(var i=0;i<len;i++){ ir[i] = rng() * Math.exp(-i/len*decay); }
  return ir;
}
function convolveProcess(samples, ir){
  var n = samples.length, m = ir.length;
  var out = new Array(n + m - 1).fill(0);
  for(var i=0;i<n;i++){
    var x = samples[i];
    for(var j=0;j<m;j++){ out[i+j] += x * ir[j]; }
  }
  var peak = 0;
  for(var k=0;k<out.length;k++){ var a=Math.abs(out[k]); if(a>peak)peak=a; }
  if(peak > 1){ for(var k=0;k<out.length;k++) out[k] /= peak; }
  return out;
}
function convolveAnalyze(samples, opts){
  opts = opts || {};
  var ir = opts.ir || makeImpulse(opts.decay, opts.len, opts.seed);
  var out = convolveProcess(samples, ir);
  var peak=0, sum=0;
  for(var i=0;i<out.length;i++){ var a=Math.abs(out[i]); if(a>peak)peak=a; sum+=out[i]*out[i]; }
  return { inLength: samples.length, irLength: ir.length, outLength: out.length, peak: peak, rms: Math.sqrt(sum/out.length) };
}

var EXPORTS={convolveAnalyze:convolveAnalyze,makeImpulse:makeImpulse,convolveProcess:convolveProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ConvolverForgePure = EXPORTS; }
